import {paintFurnitureContact} from './contact-shadow.js?v=5.1.0';
/** Furniture uses floor footprints, with restrained vertical projection and drawn construction details. */
const T=48;
export function drawDesignedFurniture(c,b){if(!b.type)return false;const type=b.type,x=b.x*T,y=b.y*T,w=b.w*T,h=b.h*T;
 paintFurnitureContact(c,b,{opacity:.15});c.save();c.translate(x,y);c.lineWidth=1.5;
 const box=(wood='#775439',lift=10)=>{c.fillStyle='#382a23';c.fillRect(3,-lift,w-6,h+lift);const g=c.createLinearGradient(0,-lift,w,h);g.addColorStop(0,wood);g.addColorStop(1,'#453629');c.fillStyle=g;c.fillRect(3,-lift,w-6,h-3);c.strokeStyle='#d5b98555';c.strokeRect(6,-lift+3,w-12,h-9);};
 const ellipse=(cx,cy,rx,ry,color)=>{c.fillStyle=color;c.beginPath();c.ellipse(cx,cy,Math.max(1,rx),Math.max(1,ry),0,0,Math.PI*2);c.fill();};
 const paper=(px=10,py=6)=>{c.fillStyle='#d0bf90';c.fillRect(px,py,Math.min(28,w-16),18);c.strokeStyle='#72695499';for(let j=0;j<3;j++){c.beginPath();c.moveTo(px+4,py+5+j*4);c.lineTo(px+20,py+5+j*4);c.stroke();}};
 const pot=(px,py,color='#7c9c8d')=>{ellipse(px,py,8,5,color);c.fillStyle=color;c.fillRect(px-7,py-10,14,10);ellipse(px,py-10,7,4,'#273b3b');};
 const candle=()=>{ellipse(w/2,h/2,12,6,'#807351');c.fillStyle='#d5c7a0';c.fillRect(w/2-3,h/2-30,6,29);ellipse(w/2,h/2-33,3,6,'#ffd795');};
 if(['bed','cot','bedroll'].includes(type)){box(type==='cot'?'#647c78':'#65513f',5);c.fillStyle='#d6c9a6';c.beginPath();c.roundRect(8,0,w-16,h-9,5);c.fill();c.fillStyle=type==='cot'?'#d4ded2':type==='bedroll'?'#847261':'#668c89';c.fillRect(9,19,w-18,h-32);c.fillStyle='#e6dfc7';c.beginPath();c.roundRect(11,1,w-22,18,5);c.fill();c.strokeStyle='#a6b6a155';for(let i=0;i<3;i++){c.beginPath();c.moveTo(13,30+i*18);c.lineTo(w-13,30+i*18);c.stroke();}}
 else if(['shelf','medicine','linen','strings','reedrack','keyrack','parts','toolrack','noticeboard'].includes(type)){box(type==='medicine'?'#58756b':'#72543c',26);for(let j=0;j<2;j++){const py=-18+j*27;c.fillStyle='#292724';c.fillRect(8,py,w-16,21);c.fillStyle='#a07d50';c.fillRect(7,py+21,w-14,4);for(let i=0;i<Math.floor((w-15)/13);i++){const px=11+i*13;if(['medicine','parts'].includes(type)){pot(px+3,py+16,['#97b4a5','#bfaa79','#708f9b'][i%3]);}else if(type==='linen'){c.fillStyle=i%2?'#b9c8ba':'#e0d3ad';c.fillRect(px,py+11,10,8);}else if(type==='keyrack'||type==='toolrack'){c.strokeStyle='#bfc0aa';c.beginPath();c.moveTo(px+4,py+3);c.lineTo(px+4,py+17);c.lineTo(px+8,py+17);c.stroke();}else if(type==='noticeboard')paper(px,py+2);else{c.fillStyle=['#728878','#a5825e','#9b645e','#a5a486'][i%4];c.fillRect(px,py+4,8,16);c.fillStyle='#d1b883';c.fillRect(px+1,py+7,6,1);}}}}
 else if(['dresser','cabinet','cupboard','trunk','nightstand'].includes(type)){box('#795b42',20);for(let j=0;j<2;j++){c.strokeStyle='#b9956355';c.strokeRect(8,-14+j*25,w-16,21);ellipse(w/2,-4+j*25,3,2,'#c6aa6a');}if(type==='nightstand')pot(w/2,0);}
 else if(['hearth','kiln'].includes(type)){box('#736e63',27);c.fillStyle='#1e2527';c.fillRect(10,-13,w-20,h+8);c.strokeStyle='#998d77';for(let i=0;i<3;i++){c.beginPath();c.moveTo(4,-20+i*19);c.lineTo(w-4,-20+i*19);c.stroke();}ellipse(w/2,h*.4,10,15,'#d68c4e');ellipse(w/2,h*.4+3,5,10,'#f7cc7e');c.fillStyle='#3a3027';c.fillRect(11,h-7,w-22,5);}
 else if(['table','maptable','desk','counter','bench','sawbench','lensbench','vice','pew','altar'].includes(type)){box(type==='altar'?'#8e8c7e':'#87623e',9);c.fillStyle='#382b23';for(const px of[8,w-15])c.fillRect(px,h-8,7,12);if(['desk','maptable'].includes(type)){paper(w*.25,3);if(type==='maptable'){c.strokeStyle='#6a8b84';c.beginPath();c.moveTo(w*.3,6);c.lineTo(w*.5,20);c.lineTo(w*.4,30);c.lineTo(w*.7,35);c.stroke();}pot(w-15,8,'#6c7a81');}else if(type==='table'){c.fillStyle='#c4ab83';c.fillRect(w*.3,-4,w*.4,h-5);ellipse(w*.5,15,13,9,'#d4cfaf');ellipse(w*.5,14,7,4,'#a66b44');pot(w*.2,15);}else if(type==='sawbench'||type==='bench'||type==='vice'){c.fillStyle='#b99865';c.fillRect(13,3,w*.5,12);c.strokeStyle='#bbc2b0';c.lineWidth=4;c.beginPath();c.moveTo(w-29,-4);c.lineTo(w-15,20);c.stroke();}else if(type==='pew'){c.fillStyle='#564533';c.fillRect(3,-15,w-6,9);}else if(type==='altar'){c.fillStyle='#c1b3a4';c.fillRect(w*.3,-8,w*.4,h+2);candle();}else if(type==='lensbench'){ellipse(w*.5,13,17,12,'#769da2');ellipse(w*.5,13,12,8,'#b4d5cd');}else{paper();}}
 else if(['chair','stool'].includes(type)){box('#705338',3);if(type==='chair'){c.fillStyle='#59422e';c.fillRect(5,-25,w-10,27);c.strokeStyle='#c5a36755';c.strokeRect(8,-22,w-16,21);}c.fillStyle='#9c7750';c.fillRect(6,5,w-12,h-13);}
 else if(['barrel','sack','basket','crate','clay','timber','rope','coil'].includes(type)){if(type==='crate'){box('#896c47',8);c.strokeStyle='#bca16c';c.beginPath();c.moveTo(7,-3);c.lineTo(w-7,h-8);c.moveTo(w-7,-3);c.lineTo(7,h-8);c.stroke();}else if(type==='timber'){for(let i=0;i<3;i++){c.fillStyle=['#9b784c','#78563b','#ad8959'][i];c.fillRect(4,2+i*12,w-8,10);ellipse(w-5,7+i*12,4,5,'#ccb47b');}}else if(type==='rope'||type==='coil'){for(let i=0;i<5;i++){c.strokeStyle=type==='rope'?'#b39c70':'#9e754b';c.lineWidth=3;c.beginPath();c.ellipse(w/2,h/2,7+i*3,4+i*2,0,0,7);c.stroke();}}else{ellipse(w/2,h*.55,w*.4,h*.42,type==='sack'?'#aa9873':type==='clay'?'#82978c':'#7e6042');ellipse(w/2,h*.25,w*.38,h*.15,'#b49a68');c.strokeStyle='#453d32';c.beginPath();c.ellipse(w/2,h*.45,w*.38,h*.18,0,0,7);c.stroke();}}
 else if(['washstand','soup','urn','wheel','scale'].includes(type)){box('#6f6651',5);ellipse(w/2,h*.4,w*.35,h*.24,'#bcbba1');ellipse(w/2,h*.36,w*.27,h*.17,type==='soup'?'#8f613d':type==='wheel'?'#9a6e57':'#779b9e');if(type==='wheel')pot(w/2,h*.3,'#bd9672');if(type==='scale'){c.strokeStyle='#d0b47c';c.lineWidth=3;c.beginPath();c.moveTo(w/2,h*.6);c.lineTo(w/2,-20);c.moveTo(6,-13);c.lineTo(w-6,-13);c.stroke();for(const px of[10,w-10]){c.lineWidth=1;c.beginPath();c.moveTo(px,-13);c.lineTo(px,8);c.stroke();ellipse(px,9,9,3,'#b4a57f');}}}
 else if(['pump','pipe','valve','console','scope'].includes(type)){box('#4f6e6a',18);c.strokeStyle='#a4ada1';c.lineWidth=5;c.beginPath();c.moveTo(w*.3,h*.8);c.lineTo(w*.3,-13);c.lineTo(w*.7,-13);c.stroke();if(type==='console'){c.fillStyle='#183b3d';c.fillRect(w*.45,-7,w*.4,22);c.strokeStyle='#afc5a0';c.lineWidth=1;c.beginPath();c.moveTo(w*.49,5);c.lineTo(w*.6,0);c.lineTo(w*.68,8);c.lineTo(w*.8,3);c.stroke();}else{c.strokeStyle='#c0a97a';c.lineWidth=3;c.beginPath();c.ellipse(w*.6,h*.3,12,12,0,0,7);c.moveTo(w*.6-10,h*.3);c.lineTo(w*.6+10,h*.3);c.stroke();}}
 else if(['piano','bell','plinth','lectern','candle','privacy','planter'].includes(type)){if(type==='candle')candle();else if(type==='planter'){box('#605844',2);for(let i=0;i<4;i++){const px=9+i*(w-16)/4;c.strokeStyle='#8eab77';c.beginPath();c.moveTo(px,h-6);c.lineTo(px,0);c.stroke();ellipse(px-3,9,7,3,'#6e945f');ellipse(px+4,1,8,3,'#9eaf78');}}else if(type==='privacy'){c.strokeStyle='#b7b49c';c.lineWidth=3;c.strokeRect(3,-26,w-6,h+25);c.fillStyle='#c3c8b4';c.fillRect(6,-23,w-12,h+18);c.strokeStyle='#939f8b';for(let i=0;i<6;i++){c.beginPath();c.moveTo(8+i*(w-16)/6,-20);c.lineTo(8+i*(w-16)/6,h-9);c.stroke();}}else if(type==='piano'){box('#4a3933',22);c.fillStyle='#d5cfb2';c.fillRect(8,h*.35,w-16,h*.4);for(let i=0;i<12;i++){c.fillStyle='#292b29';c.fillRect(10+i*(w-19)/12,h*.35,3,12);}}else if(type==='bell'){box('#655c4c',7);c.fillStyle='#bb9960';c.beginPath();c.moveTo(w*.28,-8);c.quadraticCurveTo(w/2,-40,w*.72,-8);c.lineTo(w*.82,h*.55);c.lineTo(w*.18,h*.55);c.closePath();c.fill();ellipse(w/2,h*.55,w*.34,5,'#6f6245');}else{box('#7f7d6b',14);if(type==='lectern')paper(8,-13);else ellipse(w/2,0,w*.25,9,'#9ab7af');}}
 else{c.restore();return false;}c.restore();return true;}
